import React, { useState, useContext } from 'react';
import { useParams } from 'react-router-dom';
import { StatsContext } from '../../context/StatsContext';

export default function CourseImportField() {

  const { courseId } = useParams();
  const { dashboardData } = useContext(StatsContext);
  const fields = dashboardData?.form || [];

  const initialFormData = fields.reduce((acc, field) => {
    acc[field.name] = field.type === 'checkbox' ? false : '';
    return acc;
  }, { email: '' }); 

  const [formData, setFormData] = useState(initialFormData);
  const [message, setMessage] = useState(null);
  const [loading, setLoading] = useState(false);


  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const missingRequired = fields.some(
      field => field.required && !formData[field.name]
    );

    if (!formData.email || missingRequired) {
      setMessage("Veuillez remplir tous les champs obligatoires.");
      return;
    }

    setLoading(true);
    setMessage(null);
    const formcontent = {
      rows: JSON.stringify([formData]),
      cohort: "",
    };

    var formBody = [];
    for (var property in formcontent) {
      var encodedKey = encodeURIComponent(property);
      var encodedValue = encodeURIComponent(formcontent[property]);
      formBody.push(encodedKey + "=" + encodedValue);
    }
    formBody = formBody.join("&");

    try {
      const response = await fetch(`/wul_apps/dashboard/${encodeURIComponent(courseId)}/wul_dashboard_upload_csv`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
          'Accept': 'application/json, text/javascript, */*; q=0.01',
          'X-CSRFToken': dashboardData?.csrf_token || '',
          'X-Requested-With': 'XMLHttpRequest',
        },
        processData: false,
        body: formBody,
      });

      const data = await response.json();
      if (response.ok && data.request_status !== "failed") {
        setMessage('Utilisateur ajouté avec succès !');
        setFormData(initialFormData);
      } else {
        setMessage(`Erreur : ${data.status || 'Échec de l\'ajout.'}`);
      }
    } catch (err) {
      setMessage(`Erreur réseau : ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>

      <div>
        <label>Email :</label><br />
        <input
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          required
        />
      </div>
      {fields.map((field) => {
        const { name, label, type, options, required } = field;

        if (type === 'checkbox') {
          return (
            <div key={name}>
              <label>
                <input
                  type="checkbox"
                  name={name}
                  checked={formData[name]}
                  onChange={handleChange}
                />
                {label}
              </label>
            </div>
          );
        }

        if (type === 'select') {
          return (
            <div key={name}>
              <label>{label} :</label><br />
              <select name={name} value={formData[name]} onChange={handleChange} required={required}>
                <option value=""></option>
                {options?.filter(opt => opt.value !== '').map((opt, idx) => (
                  <option key={idx} value={opt.name}>
                    {opt.value}
                  </option>
                ))}
              </select>
            </div>
          );
        }

        return (
          <div key={name}>
            <label>{label} :</label><br />
            <input
              type="text"
              name={name}
              value={formData[name]}
              onChange={handleChange}
              required={required}
            />
          </div>
        );
      })}

      <button type="submit" disabled={loading}>
        {loading ? 'Import en cours...' : 'Importer'}
      </button>
      {message && 
        <div className="statusMessage">
          <p>{message}</p>
        </div>
      }
    </form>
  );
}
