import React, {  useContext, useEffect, useState } from 'react';
import { askCertif } from '../../utils/xlsxUtils';
import { StatsContext } from '../../context/StatsContext';


export default function StudentCourseInfo({ courseId, course, customFields , id }) {

  const [allowCertif, setAllowCertif] = useState(false);
  const { dashboardData } = useContext(StatsContext);


  useEffect(() => {
    // if user already ask for the certificate
    for (const [key, value] of Object.entries(customFields)) {
            
      if (key.indexOf('success_date_' + courseId ) !== -1) {
        setAllowCertif(true);
      }
    }
    // if grade is passed
    if (course.passed) {
      setAllowCertif(true);
    }
  }, [courseId, customFields, course]);


  return (
    <div key={courseId} className="horizontal-align info-box-course">
        <div className='horizontal-align' ><strong>Nom du cours :</strong> {course.course_name}</div>
        <div className='horizontal-align' ><strong>Temps passé :</strong> {course.time_tracking} secondes</div>
        <div className='horizontal-align' ><strong>Note :</strong> <a href={course.course_grades} className="text-blue-600 underline">Voir les résultats</a></div>
        <div className='horizontal-align' ><strong>Certificat de réussite</strong> 
        {allowCertif ? (
          <button 
            onClick={() => askCertif(course.id, dashboardData, id)} 
            className="cursor-pointer text-blue-600 underline"
          >
            Obtenir une copie
          </button>
        ) : (
          <button disabled >
            Non obtenue
          </button>
        )}
        </div>
    </div>
  )

}