import React, { useContext } from 'react';
import CourseStats from '../components/Courses/CourseStats.jsx';
import { StatsContext } from '../context/StatsContext.js';
import '../css/Courses.css';

export default function Courses() {

  const { getResult, error } = useContext(StatsContext);

  if (error) return <p className='alert-msg'>{error}</p>;
  if (!getResult) return <p>Chargement des données...</p>;

  const courseList = Object.entries(getResult.coursesData).map(([courseId, courseData]) => ({
    id: courseId,
    name: courseData.name,
    countEnrollments: courseData.countEnrollments,
    finishedEnrollments: courseData.finishedEnrollments,
    abandonRate: courseData.abandonRate,
    averageProgression: courseData.averageProgression,
    averageTimeTracking: Math.round(courseData.averageTimeTracking),
  }));


  return (
    <div className='courses-page'>
      <h2>Liste des cours</h2>
      <div className='course-list'>
        {courseList.map((course) => (
          <div key={course.id} className='course-item'> 
            <CourseStats course={course} />
          </div>
        ))}
      </div>
    </div>
  );
}
