import React, { useState, useEffect } from 'react';


export default function StudentCustomFields({ customFields, fieldConfigs, userId }) {

  const [formData, setFormData] = useState(customFields || {});
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(null);
  
  useEffect(() => {
    setFormData(customFields || {});
  }, [customFields]);

  if (!fieldConfigs || Object.keys(fieldConfigs).length === 0) {
    return null;
  }

  const handleChange = (key, value) => {
    console.log(`Changement de ${key} à ${value}`);
    setFormData(prev => ({
      ...prev,
      [key]: value,
    }));
  };

  const handleSave = async () => {
    const customFieldsObj = {
      ...formData,
      authorized: true,
      user_id_for_api: userId,
    };

    setIsSaving(true);
    setSaveSuccess(null);

    try {
      const response = await fetch('/wul_apps/custom_field_editor/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRFToken': window?.jQuery?.cookie?.('csrftoken') || '',
        },
        body: JSON.stringify(customFieldsObj),
      });

      console.log("response", response);

      if (!response.ok) {
        throw new Error(`Échec de la requête : ${response.status}`);
      }
      setSaveSuccess(true);
    } catch (error) {
      console.error('Erreur :', error);
      setSaveSuccess(false);
    } finally {
      setIsSaving(false);
    }
  };




  return (
    <div className="mb-6">
      <h2 className="text-lg font-bold mb-2">Attributs utilisateur</h2>
      <table className="table-auto w-full border">
        <tbody>
          {Object.entries(fieldConfigs).map(([key, field]) => (
            <tr key={key} className="border-t">
              <td className="p-2 w-1/3">{field.label || key}</td>
              <td className="p-2">
                {field.type === 'select' ? (
                  <select
                    name={field.name}
                    value={formData[field.name] ?? ''}
                    onChange={e => handleChange(field.name, e.target.value)}
                    className="w-full border px-2 py-1"
                  >
                    <option value="" disabled>-- Sélectionner --</option>
                    {field.options?.map((option, idx) => (
                      <option key={idx} value={option.name}>
                        {option.value}
                      </option>
                    ))}
                  </select>
                ) : field.type === 'checkbox' ? (
                  <input
                    type="checkbox"
                    name={field.name}
                    checked={!!formData[field.name]}
                    onChange={e => handleChange(field.name, e.target.checked)}
                    className="mr-2"
                  />
                ) : (
                  <input
                    type={field.type}
                    name={field.name}
                    value={formData[field.name] ?? ''}
                    onChange={e => handleChange(field.name, e.target.value)}
                    placeholder={formData[field.name]  ?? ''}
                    className="w-full border px-2 py-1"
                  />
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="mt-4">
        <button
          onClick={handleSave}
          disabled={isSaving}
          className="saveCfButton"
        >
          {isSaving ? 'Enregistrement...' : 'Enregistrer'}
        </button>

        {saveSuccess === true && (
          <span className="ml-4 text-green-600">Modifications enregistrées ✅</span>
        )}
        {saveSuccess === false && (
          <span className="ml-4 text-red-600">Erreur lors de l’enregistrement ❌</span>
        )}
      </div>
    </div>
  );
}
