import React from 'react';

import { Pie } from 'react-chartjs-2';
import { Chart, ArcElement, Tooltip, Legend } from 'chart.js';

import '../../css/PieChart.css';


Chart.register(ArcElement, Tooltip, Legend);

export default function PieChart({ finished, inProgress, abandoned }) {
  const data = {
    labels: ['Terminées', 'En cours', 'Abandons'],
    datasets: [
      {
        data: [finished, inProgress, abandoned],
        backgroundColor: [
          '#4caf50', // terminées
          '#2196f3', // en cours
          '#f44336', // abandons
        ],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="pie-chart-container">
      <Pie data={data} />
    </div>
  );
}
