import React from 'react';
import StudentCourseInfo from './StudentCouseInfo';


export default function StudentCourses({ enrollments, id, customFields }) {

  const enrollmentEntries = Object.entries(enrollments || {}).filter(
    ([, course]) => course.start_date === true
  );

  return (
    <div className="mb-6">
      <h2 className="text-lg font-bold mb-2">Cours</h2>
      {enrollmentEntries.length === 0 ? (
        <p>Aucun cours trouvé.</p>
      ) : (
        enrollmentEntries.map(([courseId, course]) => (
          <StudentCourseInfo courseId={courseId} course={course} customFields={customFields} id={id}/>
        ))
      )}
    </div>
  );

}
