// src/components/StudentDetailData.jsx
import React from 'react';
import '../../css/StudentDetail.css';

import StudentInfoTable from './StudentInfoTable';
import StudentCourses from './StudentCourses';
import StudentCustomFields from './StudentCustomFields';

export default function StudentDetailData({ data }) {
  if (!data ) return <p>Données indisponibles pour l'utilisateur recherché</p>;

  return (
    <div className="p-4">
      <StudentInfoTable info={data} />
      <div className="vertical-align">
        <StudentCourses enrollments={data.enrollments || {} } id={data.id || {}} customFields={data.custom_field || {}} />
        <StudentCustomFields customFields={data.custom_field || {}} fieldConfigs={data.field_configs || {}}   userId={data.id} />
      </div>
    </div>
  );
}
