import ExcelJS from "exceljs";
import { saveAs } from "file-saver";



export const askCertif = async (courseId, dashboardData, id) => {
  const dataContent = {
    userId: id,
    courseId: courseId
  };
  const body = JSON.stringify(dataContent);
  
  try {
    const response = await fetch(`/wul_apps/api/generate_pdf_from_datavis`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json', 
        'X-CSRFToken': dashboardData?.csrf_token || '',
        'X-Requested-With': 'XMLHttpRequest',
      },
      // processData: false,
      body: body,
    });

    if (!response.ok) {
      throw new Error(`Erreur serveur: ${response.status}`);
    }

    const blob = await response.blob();
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.download = `certificat_${id}.pdf`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.URL.revokeObjectURL(url);

  } catch (error) {
    alert(`Erreur réseau : ${error.message}`);
  }

}




export const getExcelColumnLetter = (colIndex) => {
  let letter = "";
  while (colIndex >= 0) {
    letter = String.fromCharCode((colIndex % 26) + 65) + letter;
    colIndex = Math.floor(colIndex / 26) - 1;
  }
  return letter;
};

const createWorkbook = () => {
  const workbook = new ExcelJS.Workbook();
  const formSheet = workbook.addWorksheet("Formulaire");
  const optionsSheet = workbook.addWorksheet("Options");
  return { workbook, formSheet, optionsSheet };
};

const addHeadersAndEmptyRows = (formSheet, headers, emptyRowCount) => {
  formSheet.addRow(headers);
  for (let i = 0; i < emptyRowCount; i++) {
    formSheet.addRow(Array(headers.length).fill(""));
  }
};

const fillOptionsSheet = (optionsSheet, allOptionFields) => {
  allOptionFields.forEach((field, idx) => {
    const colIndex = idx + 1;
    const values =
      field.type === "checkbox"
        ? ["true", "false"]
        : field.options.filter((opt) => opt.value).map((opt) => opt.value);

    values.forEach((val, rowIdx) => {
      optionsSheet.getCell(rowIdx + 1, colIndex).value = val;
    });
  });
};

const addDropdownValidations = (
  formSheet,
  headers,
  allOptionFields,
  emptyRowCount
) => {
  allOptionFields.forEach((field, idx) => {
    const fieldColIndex = headers.indexOf(field.label) + 1;
    const optColLetter = getExcelColumnLetter(idx);
    const valuesCount = field.type === "checkbox" ? 2 : field.options.length;

    for (let i = 2; i <= emptyRowCount + 1; i++) {
      const cell = formSheet.getCell(i, fieldColIndex);
      cell.dataValidation = {
        type: "list",
        allowBlank: true,
        formulae: [`Options!$${optColLetter}$1:$${optColLetter}$${valuesCount}`],
        showErrorMessage: true,
        errorTitle: "Valeur invalide",
        error: "Veuillez choisir une valeur dans la liste déroulante",
      };
    }
  });
};

const addEmailValidation = (formSheet, emptyRowCount) => {
  const emailColIndex = 1;
  for (let i = 2; i <= emptyRowCount + 1; i++) {
    const cell = formSheet.getCell(i, emailColIndex);
    cell.dataValidation = {
      type: "custom",
      formulae: [`ISNUMBER(FIND("@", A${i}))`],
      allowBlank: false,
      showErrorMessage: true,
      errorTitle: "Email invalide",
      error: "Veuillez saisir une adresse email valide",
    };
  }
};




export const handleDownloadEmptyXlsx = async (formFields, fileName = "fichier_import.xlsx") => {
  const emptyRowCount = 500;
  const headers = ["email", ...formFields.map((field) => field.label)];
  const { workbook, formSheet, optionsSheet } = createWorkbook();

  addHeadersAndEmptyRows(formSheet, headers, emptyRowCount);

  const selectFields = formFields.filter(
    (field) => field.type === "select" && field.options
  );
  const checkboxFields = formFields.filter((field) => field.type === "checkbox");
  const allOptionFields = [...selectFields, ...checkboxFields];

  fillOptionsSheet(optionsSheet, allOptionFields);
  addDropdownValidations(formSheet, headers, allOptionFields, emptyRowCount);
  addEmailValidation(formSheet, emptyRowCount);

  optionsSheet.state = "veryHidden";
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  });
  saveAs(blob, fileName);
};
