import React, { useState } from 'react';
import '../css/StudentDetail.css';
import StudentDetailData from '../components/StudentDetail/StudentDetailData.jsx';


export default function StudentDetail() {

  const [getResult, setGetResult] = useState(null);
  const [error, setError] = useState(null);
  const [email, setEmail] = useState(null);
  const [emailTouched, setEmailTouched] = useState(false);

  function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  async function getStudentProfile() {
    try {

      setError(null);
      const res = await fetch(`/wul_apps/dashboard/get_student_profile/${email}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!res.ok) {
        throw new Error(`Erreur HTTP : ${res.status}`);
      }

      const result = await res.json();
      console.log("result");
      console.log(result);
      console.log(result.enrollments);
      

      if (Object.keys(result).length === 0) {
        setError("Il n'existe pas d'utilisateur correspondant à cet e-mail.");
        setGetResult(null);
        return;
      }


      for (const [key, value] of Object.entries(result.enrollments)) {

        if (!value.enrolled_to_enrollment) {
          console.log("No enrolled_to_enrollment found");
          
          setError("L'utilisateur n'est inscrit à aucun cours.");
          setGetResult(null);
          return;
        }
      }



      setGetResult(result);
      console.log('result GET user specific', result);

    } catch (error) {

      console.error(error);
      setError("Il n'existe pas d'utilisateur correspondant à cet e-mail.");
      setGetResult(null);

    }
  }

  return (
    <div className='studentDetailContainer'>
      <div className='studentSearchContainer'>
        <h2>Étudiant spécifique</h2>
        <input
          type="text"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          onBlur={() => setEmailTouched(true)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && isValidEmail(email)) {
              getStudentProfile();
            }
          }}
          placeholder="Entrez l'email de l'étudiant"
          className='inputField'
        />
        {emailTouched && !isValidEmail(email) && (
          <div className='errorMessage'>
            Veuillez entrer un email valide.
          </div>
        )}
        <button onClick={getStudentProfile} disabled={!isValidEmail(email)} >
          Rechercher
        </button>
      </div>
      {!error && getResult && (
        <StudentDetailData data={getResult} />
      )}
      {error && (
        <div className='errorMessage'>
          {error}
        </div>
      )}
    </div>
  );
}
