// src/context/StatsContext.js
import React, { createContext, useState, useEffect } from 'react';

export const StatsContext = createContext();

export const StatsProvider = ({ children }) => {
  const [getResult, setGetResult] = useState(null);
  const [dashboardData, setDashboardData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        console.log('début du GET');
        console.log('process.env.NODE_ENV', process.env.NODE_ENV);

        const url =
          process.env.NODE_ENV === 'development'
            ? '/get_1806.json'
            : '/wul_apps/api/stats';
        // A MODIFIER POUR LA PRODUCTION 
        // A MODIFIER POUR LA PRODUCTION 
        // A MODIFIER POUR LA PRODUCTION

        console.log('url', url);

        const res = await fetch(url, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
        });

        if (!res.ok) {
          throw new Error(`Erreur HTTP sur stats: ${res.status}`);
        }

        const result = await res.json();
        console.log('result GET', result);
        setGetResult(result);
      } catch (err) {
        console.error('GET Error:', err);
        setError('Erreur lors du GET vers stats');
      }

      try {
        const url2 =
          process.env.NODE_ENV === 'development'
            ? '/get_2_1806.json'
            : '/wul_apps/api/dashboard_data';

        const res2 = await fetch(url2, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
        });

        if (!res2.ok) {
          throw new Error(`Erreur HTTP sur dashboard_data: ${res2.status}`);
        }

        const data = await res2.json();
        console.log('Dashboard Data:', data);
        setDashboardData(data);
      } catch (err) {
        console.error('Dashboard Data Error:', err);
        setError('Erreur lors du GET vers dashboard_data');
      }
    };

    fetchData();
  }, []);

  return (
    <StatsContext.Provider value={{ getResult, dashboardData, error }}>
      {children}
    </StatsContext.Provider>
  );
};
