import React, {useContext, useMemo} from 'react';
import { StatsContext } from '../context/StatsContext.js';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import '../css/HomePage.css';


export default function GeneralInfo() {
  const { getResult, error } = useContext(StatsContext);

  const enrollmentData = useMemo(() => {
    if (!getResult?.enrollmentDates) return [];
    const counts = {};

    // Compter les inscriptions par mois
    getResult.enrollmentDates.forEach(dateStr => {
      const [year, month] = dateStr.split('-'); // format YYYY-MM-DD
      const key = `${year}-${month}`;
      counts[key] = (counts[key] || 0) + 1;
    });

    // Générer les 12 derniers mois dynamiquement
    const now = new Date();
    const months = [];
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      months.push({
        month: d.toLocaleString('fr-FR', { month: 'short', year: 'numeric' }),
        inscriptions: counts[key] || 0
      });
    }

    return months;
  }, [getResult]);

  function parseDate(dateStr) {
    const [day, month, year] = dateStr.split('-').map(Number);
    return new Date(year, month - 1, day); // mois en JS : 0-11
  }

  if (error) {return <p className='alert-msg'>{error}</p>;}
  if (!getResult) {return <p>Chargement des données...</p>;}

  // Vérifier la date limite de maintenance
  const today = new Date();
  const deadline = parseDate(getResult.maintenanceDeadline);
  const diffTime = deadline - today;
  const diffDays = diffTime / (1000 * 3600 * 24);
  const isCritical = diffDays <= 30;

  return (
    <div className="general-info">

      <div className='horizontal-align'>
        <div className='global-stats'>
          <h2>Nombre d'inscrits sur la plateforme</h2>
          <p>{getResult.totalUserOrg}</p>
        </div>
        <div className='global-stats'>
          <h2>Nombre de cours ouvert </h2>
          <p>{getResult.coursesCount}</p>
        </div>
        <div className='global-stats'>
          <h2>Date de fin de maintenance de la plateforme </h2>
          <p style={{ color: isCritical ? 'red' : 'inherit' }}>
            {getResult.maintenanceDeadline}
          </p>
        </div>
      </div>
      <div className="horizontal-align full-width">
        {/* Graphique des inscriptions par mois */}
        <div className="chart-container" >
          <h2>Inscriptions par mois</h2>
          <ResponsiveContainer>
            <BarChart 
              data={enrollmentData} 
              // width={2600} 
              // height={300}
              // margin={{ top: 20, right: 20, left: 20, bottom: 5, }} 
            >
              <XAxis 
                dataKey="month"
                // stroke="#000000"
                // domain={[0.5,12.5]} 
                // ticks={["Janvier", 6, 7, 8, 9, 10, 11, 12, 13]}
              />
              <YAxis allowDecimals={false} />
              <Tooltip />
              <Bar dataKey="inscriptions" fill="#72db89ff" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

    </div>
  );
}
