
import React, { useState, useContext } from 'react';
import { useParams } from 'react-router-dom';
import { StatsContext } from '../../context/StatsContext';
import ExcelJS from "exceljs";
import { handleDownloadEmptyXlsx } from "../../utils/xlsxUtils";


export default function CourseImportXlsx() {

  const [message, setMessage] = useState(null);
  const [parsedData, setParsedData] = useState(null);
  const [loading, setLoading] = useState(false);

  const { courseId } = useParams();
  const { dashboardData } = useContext(StatsContext);


  // Requete POST pour l'import Xlsx
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!parsedData) {
      setMessage('Veuillez sélectionner un fichier à importer.');
      return;
    }
    setLoading(true);
    setMessage(null);
    var formBody = [];
    const formcontent = {
      rows: JSON.stringify(parsedData.validRows),
      cohort: "",
    };

    for (var property in formcontent) {
      var encodedKey = encodeURIComponent(property);
      var encodedValue = encodeURIComponent(formcontent[property]);
      formBody.push(encodedKey + "=" + encodedValue);
    }
    formBody = formBody.join("&");

    try {
      const response = await fetch(`/wul_apps/dashboard/${encodeURIComponent(courseId)}/wul_dashboard_upload_csv`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
          'Accept': 'application/json, text/javascript, */*; q=0.01',
          'X-CSRFToken': dashboardData?.csrf_token || '',
          'X-Requested-With': 'XMLHttpRequest',
        },
        processData: false,
        body: formBody,
      });
      const data = await response.json();

      if (response.ok && data.request_status !== "failed") {
        setMessage('Import réussi !');
        setParsedData(null);
      } else {
        setMessage(`Erreur : ${data.status || 'Échec de l\'ajout. Veuillez contacter un administrateur ( sysadmin@weuplearning.com ).'}`);
      }

    } catch (error) {
      setMessage(`Erreur réseau : ${error.message}`);
    } finally {
      setLoading(false);
    }
  };


  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setMessage(null);

    try {
      const formFields = dashboardData.form;
      const labelToNameMapHeader = {};
      const valueToNameMapSelect = {};
      const requiredFields = formFields
        .filter(field => field.required)
        .map(field => field.name);

      formFields.forEach(field => {
        labelToNameMapHeader[field.label] = field.name;

        if (field.type === 'select' && field.options) {
          field.options.forEach(opt => {
            valueToNameMapSelect[opt.value] = opt.name;
          });
        }
      });

      const workbook = new ExcelJS.Workbook();
      await workbook.xlsx.load(await file.arrayBuffer());

      const worksheet = workbook.getWorksheet('Formulaire');
      const headerRow = worksheet.getRow(1).values.slice(1);
      const valueHeaders = headerRow.map(label => labelToNameMapHeader[label] || label);
      const validRows = [];
      let requiredError = [];

      worksheet.eachRow((row, rowNumber) => {
        if (rowNumber === 1) return;
        const rowData = {};

        // Eviter les lignes vides
        if (row.values.every(cell => cell === null || cell === '')) return;

        valueHeaders.forEach((fieldValue, idx) => {
          const cell = row.getCell(idx + 1);
          let rawValue = '';          

          if ((requiredFields.includes(fieldValue) && cell.value === "") || (fieldValue === 'email' && !cell.value)) {
            requiredError.push(`Valeur manquante à la cellule ${idx + 1} de la ligne ${rowNumber} : ${fieldValue}`)
          }

          // Mise en forme nécessaire pour les cellules ExcelJS
          if (typeof cell.value === 'object' && cell.value !== null) {
            if ('text' in cell.value) {
              rawValue = cell.value.text.trim();
            } else if (Array.isArray(cell.value.richText)) {
              rawValue = cell.value.richText.map(rt => rt.text).join('').trim();
            } else {
              rawValue = String(cell.value.result || cell.value.formula || '').trim();
            }
          } else {
            rawValue = String(cell.value || '').trim();
          }

          if ( valueToNameMapSelect[rawValue] ) {
            rawValue = valueToNameMapSelect[rawValue] ;
          }

          rowData[fieldValue] = rawValue;
        });

        if (rowData.email && rowData.email.includes('@')) {
          validRows.push(rowData);
        }
      });


      if (requiredError.length > 0) {
        setMessage(`Erreur : ${requiredError.join(', ')}`);
        return;
      }

      setParsedData({ validRows }); 
      setMessage(`${validRows.length} lignes prêtes à être importées.`);

    } catch (error) {
      setMessage(`Erreur lors du traitement du fichier : ${error.message}. Veuillez reprendre la procédure décrite.`);
    }
  };


  return (
    <div className="courseImportXlsx">
      <div className='helperImportXlsx'>
        <p>Inscrivez une liste d'utilisateurs à ce cours à partir d'un tableur Excel :</p>
        <ol>
          <li>Récupérez le modèle de fichier correspondant à votre formulaire d'inscription.</li>
          <li>Ajoutez au tableau une ligne pour chaque nouvel utilisateur que vous souhaitez inscrire (500 utilisateurs max par fichier) </li>
          <li>Déposez le fichier sur la zone prévue à cet effet</li>
          <li>Démarrez l'import en cliquant sur le bouton "Importer"</li>
          <li>Vous serez notifié par E-mail de l'état d'avancement d'ici quelques minutes.</li>
        </ol>
      </div>
      <div className='top-spacer downloadXlsx' >
        <button onClick={() => handleDownloadEmptyXlsx(dashboardData.form)}>
          Télécharger un tableur Excel vide
        </button>
      </div>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="fileInput">Fichier d'import :</label><br />
          <input
            type="file"
            accept=".xlsx"
            onChange={handleFileChange}
            disabled={loading}
          />
        </div>
        <button type="submit" disabled={loading}>
          {loading ? 'Import de participants en cours...' : 'Importer'}
        </button>
      </form>
      {message && 
        <div className="statusMessage">
          <p>{message}</p>
        </div>
      }
    </div>
  );
}
