import React, { useContext } from 'react';
import { useLocation, useParams, useNavigate } from 'react-router-dom';
import { StatsContext } from '../context/StatsContext';


export default function CourseDetail() {

  const { courseId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const { dashboardData } = useContext(StatsContext);
  const course = location.state?.course;

  // Fonction pour appeler l'API de génération de rapport
  const handleGenerateReport = async () => {
    try {
      const response = await fetch(`/wul_apps/dashboard/${encodeURIComponent(courseId)}/stat_dashboard/xls_grade_reports/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRFToken': dashboardData.csrf_token || '',
        },
        body: JSON.stringify({ 
          courseId: courseId,
          fields: ["user_id", "email", "first_name", "last_name", "inscription_date", "last_connexion", "time_tracking"],
          receivers: [dashboardData.user_email],
          scope : {intern: true, admin: false}
        }),
      });

      const data = await response.json();


      if (response.ok && data.request_status !== "failed") {

        alert('Votre demande a été transmise et le rapport de notes est en cours de création. Vous recevrez ce rapport par e-mail dès qu’il sera prêt.');
      } else if (response.status === 403) {
        alert('Erreur : Vous n\'êtes pas autorisé à générer ce rapport.');
      } else if (response.status === 404) {
        alert('Erreur : Cours non trouvé.');
      } else {
        alert(data.status || 'Erreur lors de la génération du rapport.');
      }
    } catch (error) {
      alert('Erreur réseau : ' + error.message);
    }
  };

  if (!course) return <p>Aucun cours disponible.</p>;

  return (
    <div>
      <section className='course-detail-header'>
        <h2>Détails du cours : {course.name}</h2>
        <div className='course-detail-header-points'>
          <div>
            <strong>Nombre d'inscrits :</strong> {course.countEnrollments}
          </div>
          <div>
            <strong>Utilisateurs actifs :</strong> {course.activeUsers || 'N/A'}
          </div>
          <div>
            <strong>Temps passé moyen :</strong> {Math.round(course.averageTimeTracking)} secondes
          </div>
          <div>
            <strong>Note moyenne :</strong> {course.averageScore ? course.averageScore.toFixed(2) : 'N/A'}
          </div>
        </div>
      </section>

      <section>
        <button 
          onClick={() => navigate(`/wul_apps/data_visualisation/courses/${encodeURIComponent(courseId)}/import`)}
          className='course-detail-button'
        >
          Inscrire un apprenant
        </button>
        <button 
          onClick={() => navigate('/wul_apps/data_visualisation/student')}
          className='course-detail-button'
        >
          Suivre un apprenant
        </button>
        <button className='course-detail-button' >
          <a href={`https://studio.weup.in/course/${encodeURIComponent(courseId)}`} target="_blank" rel="noopener noreferrer">
            Modifier le cours
          </a>
        </button>
        <button 
          onClick={handleGenerateReport} 
          className='course-detail-button'
        >
          Générer un rapport de notes
        </button>
      </section>
    </div>
  );
}
