import React from 'react';
import { Link } from 'react-router-dom';
import PieChart from './PieChart';


export default function CourseStats({ course }) {
  if (!course) return <p>Données du cours indisponibles.</p>;

  return (
    <div className='course-info-container' >
      <div 
        className="course-stats vertical-align space-between"
      >

        <h3>Statistiques du cours : {course.name}</h3>
        <p><strong>Nombre d'inscriptions :</strong> {course.countEnrollments}</p>

        <PieChart
          finished={course.finishedEnrollments}
          inProgress={course.countEnrollments - course.finishedEnrollments - Math.round(course.abandonRate * course.countEnrollments)}
          abandoned={Math.round(course.abandonRate * course.countEnrollments)}
        />

        <p><strong>Progression moyenne :</strong> {(course.averageProgression * 100).toFixed(2)}%</p>
        <p><strong>Temps moyen passé :</strong> {Math.round(course.averageTimeTracking)} secondes</p>
        <Link 
          to={`/wul_apps/data_visualisation/courses/${encodeURIComponent(course.id)}`} 
          state={{ course }}
        >Voir les détails</Link>
      </div>
    </div>
  );
}
