import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

import CourseImportXlsx from '../components/Courses/CourseImportXlsx';  
import CourseImportField from '../components/Courses/CourseImportField';  

import '../css/CourseImport.css';

export default function CourseImport() {
  
  const { courseId } = useParams();
  const navigate = useNavigate();


  const [importMode, setImportMode] = useState('xlsx'); 

  return (
    <div>
      <h2>Importer des apprenants dans le cours {courseId}</h2>
      {/* Choix du mode */}
      <div className='import-header'>
        <button
          onClick={() => setImportMode('xlsx')}
          className={importMode === 'xlsx' ? 'selected-mode' : 'not-selected-mode'}
        >
          Importer via un tableur Excel
        </button>
        <button
          onClick={() => setImportMode('manual')}
          className={importMode === 'manual' ? 'selected-mode' : 'not-selected-mode'}
        >
          Ajouter un utilisateur manuellement
        </button>
      </div>
      {/* Affichage du bon composant */}
      {importMode === 'xlsx' ? <CourseImportXlsx /> : <CourseImportField />}
      <button onClick={() => navigate(-1)} className='top-spacer'>
        Retour vers la liste de cours
      </button>
    </div>
  );
}